            var _rcAcc = (ds.rootCauseScore / 100) * 30;
            var _budgetEff = Math.max(0, (1 - ds.budgetSpent / 180000) * 0.5 + 0.5) * 20;
            var _controlComp = (ds.controlPlanScore / 100) * 15;
            var _penalties = 0;
            if (ds.baselineSigma === 0) _penalties += 20;
            if (ds.tamperedFlag) _penalties += 15;
            if (ds.rootCauseScore < 30) _penalties += 25;
            var overallScore = Math.max(0, Math.min(100, Math.round(_sigmaAch + _rcAcc + _budgetEff + _controlComp - _penalties)));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext, domainState: ds });
            })(state.currentPeriod + 1), 500);

            return results;
        }

