        getPerformanceSummary(history) {
            if (!history.length) return {};
            var lastEntry = history[history.length - 1];
            var finalSigma = lastEntry.results ? lastEntry.results.finalSigma || 0 : 0;
            var finalScore = lastEntry.results ? lastEntry.results.sigmaScore || 0 : 0;
            var finalDefect = lastEntry.results ? lastEntry.results.finalDefectRate || 0 : 0;

            var performance = window.mySimulation.t('perf_needs_improvement');
            if (finalScore >= 80) performance = window.mySimulation.t('perf_excellent');
            else if (finalScore >= 60) performance = window.mySimulation.t('perf_good');
            else if (finalScore >= 40) performance = window.mySimulation.t('perf_developing');

            var insights = [];
            if (finalSigma >= 3.8) {
                insights.push(window.mySimulation.t('insight_sigma_outstanding'));
            } else if (finalSigma >= 3.2) {
                insights.push(window.mySimulation.t('insight_sigma_meaningful'));
            } else {
                insights.push(window.mySimulation.t('insight_sigma_limited'));
            }

            var r2 = history[1];
            if (r2 && r2.results && r2.results.rootCauseScore >= 80) {
                insights.push(window.mySimulation.t('insight_rc_strong'));
            } else if (r2 && r2.results && r2.results.rootCauseScore < 40) {
                insights.push(window.mySimulation.t('insight_rc_missed'));
            }

            return {
                finalSigma: finalSigma,
                finalDefectRate: finalDefect,
                sigmaScore: finalScore,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (state.currentPeriod === 1 && results.measurementAccuracy < 60) {
                return window.mySimulation.t('hint_low_measurement');
            }
            if (state.currentPeriod === 2 && results.rootCauseScore < 40) {
                return window.mySimulation.t('hint_weak_rc');
            }
            if (state.currentPeriod === 3 && results.defectReduction < 30) {
                return window.mySimulation.t('hint_low_improvement');
            }
            if (state.currentPeriod === 4 && results.controlPlanScore < 50) {
                return window.mySimulation.t('hint_weak_control');
            }
            return null;
        }

